&lt;ul style=&quot;margin-top: 0in; margin-bottom: 0in;&quot; type=&quot;disc&quot;&gt;
&lt;li style=&quot;margin-top: 0; margin-bottom: 0; vertical-align: middle;&quot;&gt;&lt;span lang=&quot;en-GB&quot; style=&quot;font-family: Calibri; font-size: 11.0pt;&quot;&gt;Your personal information will be collected and managed by Coupang as stated in the Application Privacy Notice located below. &lt;/span&gt;&lt;a href=&quot;https://privacy.coupang.com/en/land/jobs/&quot;&gt;&lt;span lang=&quot;en-US&quot; style=&quot;font-family: Calibri; font-size: 11.0pt;&quot;&gt;https://privacy.coupang.com/en/land/jobs/&lt;/span&gt;&lt;/a&gt;&lt;span lang=&quot;en-US&quot; style=&quot;font-family: Calibri; font-size: 11.0pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
